    /** (degrees, x px, y px) for the blade {@code katana} drawn {@code out} model px out of its saya. */
    public static float[] at(Katana katana, float out) {
        float[] rows = katana == null ? null : of(katana.key());
        if (rows == null || rows.length < 6) {
            return new float[] {0.0F, 0.0F, -out};
        }
        int n = rows.length / 3;
        float x = Math.max(0.0F, out);
        int i = (int) Math.floor(x);
        if (i + 1 >= n) {
            i = n - 2;
        }
        float u = x - i;
        float[] r = new float[3];
        for (int k = 0; k < 3; k++) {
            r[k] = rows[i * 3 + k] + (rows[(i + 1) * 3 + k] - rows[i * 3 + k]) * u;
        }
        return r;
    }

